package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.text.InputType;import com.irwi.fincapp.session.SessionManager;
public class LoginActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=BaseUi.root(this);l.addView(BaseUi.title(this,"Sign in"));l.addView(BaseUi.text(this,"Use your FincApp account. Offline mode works after first login.",18));EditText email=BaseUi.input(this,"Email");EditText pass=BaseUi.input(this,"Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Button sign=BaseUi.btn(this,"Sign in");Button demo=BaseUi.btn(this,"Continue demo offline");l.addView(email);l.addView(pass);l.addView(sign);l.addView(demo);sign.setOnClickListener(v->{String e=email.getText().toString().trim();if(e.isEmpty()){BaseUi.toast(this,"Enter email");return;}new SessionManager(this).login(e);startActivity(new Intent(this,FarmActivity.class));finish();});demo.setOnClickListener(v->{new SessionManager(this).login("demo@fincapp.local");startActivity(new Intent(this,FarmActivity.class));finish();});}}
